import { defineStore } from 'pinia'
import { ref } from 'vue'

// 窗口窄于此宽度且用户未手动选择过时，侧栏默认折叠（U15）
export const SIDEBAR_AUTO_COLLAPSE_WIDTH = 1440
const STORAGE_KEY = 'sidebarCollapsed'

const readSaved = () => {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    return raw === null ? null : Boolean(JSON.parse(raw))
  } catch {
    return null
  }
}

// Generated by Copilot
export const useAppStore = defineStore('app', () => {
  // 侧边栏状态
  const sidebarCollapsed = ref(false)
  // 用户是否手动切换过侧栏：手动选择后不再随窗口宽度自动折叠 / 展开（选择持久化在 localStorage）
  const sidebarManual = ref(false)

  // 手动切换侧边栏，并记住选择
  const toggleSidebar = () => {
    sidebarCollapsed.value = !sidebarCollapsed.value
    sidebarManual.value = true
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(sidebarCollapsed.value))
    } catch {
      // 存储不可用（隐私模式等）时仅本次会话生效
    }
  }

  // 按窗口宽度自动折叠：仅在用户未手动选择时生效
  const autoCollapseByWidth = (width) => {
    if (sidebarManual.value) return
    sidebarCollapsed.value = width < SIDEBAR_AUTO_COLLAPSE_WIDTH
  }

  // 初始化应用设置：有手动选择则恢复，否则按当前窗口宽度决定
  const initAppSettings = () => {
    const saved = readSaved()
    if (saved !== null) {
      sidebarCollapsed.value = saved
      sidebarManual.value = true
      return
    }
    sidebarManual.value = false
    autoCollapseByWidth(window.innerWidth)
  }

  return {
    sidebarCollapsed,
    sidebarManual,
    toggleSidebar,
    autoCollapseByWidth,
    initAppSettings
  }
})
